// simple markdown to HTML converter (basic version)

function markdownTOhtml(markdown) {
  return markdown
    .replace(/### (.*)/g, '<h3>$1</h3>')
    .replace(/## (.*)/g, '<h2>$1</h2>')
    .replace(/# (.*)/g, '<h1>$1</h1>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/`(.*?)`/g, '<code>$1</code>')
    .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2">$1</a>');
}

const roadmapText = $input.first().json.text;
const roadmapHTML = markdownTOhtml(roadmapText);

return [
  {
    json: {
      html: roadmapHTML
    }
  }
];
